const float PI = 3.14159265359;
const float TWO_PI = 6.28318530718;
const int NUM_PARTICLES = 30;
const float PARTICLE_SCALE = 0.79;
const float FEEDBACK_MIX_FACTOR = 0.997639;
const float VISCOSITY_FALLOFF = 35.;

float sparkle(float x, float y, float time) {
    return sin(x * 10.0 + time * 10.0) * sin(y * 100.0 + time * 12.0) * 0.5 + 0.5;

}
float hash(vec2 p) {
    return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453);
}

float perlinNoise(vec2 st) {
    vec2 i = floor(st);
    vec2 f = fract(st);
    vec2 u = f * f * (3.0 - 2.2 * f);
    return mix(mix(hash(i + vec2(0.0, 0.0)), hash(i + vec2(1.0, 0.0)), u.x),
               mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), u.x),
               u.y);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord / iResolution.xy) * 2.0 - 1.0;
    uv.x *= iResolution.x / iResolution.y;
    float time = iTime * 0.95;
    vec3 color = vec3(0.05);
    const float Y_CULL_THRESHOLD = 1.5;
    for (int i = 0; i < NUM_PARTICLES; i++) {
        float id = float(i) / float(NUM_PARTICLES);
        float seed = float(i) * 123.1;
        float particleTime = fract(time + id);
        bool isTypeA = fract(sin(seed) * 43758.5453123) < perlinNoise(vec2(seed, time));
        float startX;
        float startY;
        float ySpeed;
        if (isTypeA) {
            startX = 0.03 * cos(id * TWO_PI + particleTime * (16.0 * perlinNoise(vec2(time, id)))) + 0.3149 * perlinNoise(vec2(seed, time));
            startY = -1.4;
            ySpeed = 0.7 + 0.9 * abs(sin(id * PI + time));
        } else {
            startX = 0.08 * sin(id * TWO_PI + particleTime * 5.0) + 0.313 * perlinNoise(vec2(seed, time));
            startY = -1.4;
            ySpeed = 1.3 + 0.96 * abs(cos(id * PI + time * 0.2) + 0.5);
        }
        float yOffset = particleTime * ySpeed;
        vec2 particlePos = vec2(startX, startY + yOffset) * PARTICLE_SCALE;
        if (particlePos.y > Y_CULL_THRESHOLD) continue;
        vec3 baseColor = mix(vec3(0.1, 0.3, 0.9), vec3(1.0, 0.5, 0.0), id);
        float dist = length(uv - particlePos);
        float viscosity = exp(-dist * (2.0 + VISCOSITY_FALLOFF * (0.1 + (1.353 - abs(particlePos.y)) / 2.8 + pow(particleTime, 4.0))));
       // float glitter = 0.92 * sparkle(particlePos.x, particlePos.y, time);
        float fade = smoothstep(0.1, 0.40, particleTime * dist);
        //baseColor += glitter * vec3(0.9, 0.5, 1.0);
        baseColor = baseColor * fade + baseColor/6. + fade *3.;
        color += baseColor * viscosity;
    }
    fragColor = vec4(color, 1.0);
    float vignette = pow(length(uv * 0.5), 1.0) * 0.0009118817;
    fragColor.rgb += vignette;
    float lum = length(fragColor.rgb);
    vec3 toneMapped = mix(fragColor.rgb / 1.5199187, sqrt(sqrt(fragColor.rgb)), smoothstep(0., 1.9, lum));
    fragColor.rgb = (toneMapped+fragColor.rgb)*.4;

    lum = length(fragColor.rgb);
    toneMapped = mix(fragColor.rgb / 1.399187, sqrt(sqrt(fragColor.rgb)), smoothstep(0.1, 0.5, lum));
   fragColor.rgb += toneMapped;
    fragColor.a = 1.0 - fragColor.g / 5.0;
    vec4 previousFrame = clamp(texture(iChannel0, fragCoord.xy / iResolution.xy),0.,.99);
    fragColor.rgb += previousFrame.rgb*pow(length(previousFrame.rgb)/3.,2.) * FEEDBACK_MIX_FACTOR;

}
